// 방울이 UI의 기존 데모 시나리오와 사용량 환산 데이터를 제공하는 모듈
  const COEF = {
    supply: 0.23,      // kWh/㎥ 상수도 공급
    sewage: 0.45,      // kWh/㎥ 하수 처리
    co2: 0.4173,       // kg CO₂/kWh
    hotShare: 0.45,    // 가정 물 중 온수 비율
    dT: 45,            // 온도차 60→15℃
    eff: 0.85,         // 보일러 효율
    KCAL_KWH: 0.001163,
  };
  // 온수 1L 데우는 데 드는 에너지 ≈ 0.0616 kWh
  const HOT_KWH_PER_L = (COEF.dT / COEF.eff) * COEF.KCAL_KWH;

  function energyOf(liters) {
    const m3 = liters / 1000;
    const hot = liters * COEF.hotShare * HOT_KWH_PER_L;
    const supply = m3 * COEF.supply;
    const sewage = m3 * COEF.sewage;
    const total = hot + supply + sewage;
    return {
      hot, supply, sewage, total,
      co2: total * COEF.co2,
      phoneCharges: Math.round(total / 0.015), // 스마트폰 1회 충전 ≈ 0.015kWh
    };
  }
  const PER_LITER_KWH = energyOf(1).total; // 물 1L당 환산 에너지

  // 어제 검침값 (L 누적) = 0234.412 ㎥
  const METER_YESTERDAY = 234412;
  const SCENARIOS = {
    '절약': { digits: '0234918', usage: 506 },
    '보통': { digits: '0234974', usage: 562 },
    '초과': { digits: '0235053', usage: 641 },
  };

  const STAGES = [
    { n: 1, img: 'data:image/png;base64,', name: '촉촉한 상태',   days: '오늘 기록 완료!',        msg: '최고로 촉촉하고 건강해요!' },
    { n: 2, img: 'data:image/png;base64,', name: '조금 마른 상태', days: '기록을 1~2일 놓쳤어요',  msg: '조금 수분이 부족해졌어요…' },
    { n: 3, img: 'data:image/png;base64,', name: '마른 상태',     days: '기록을 3~4일 놓쳤어요',  msg: '점점 힘이 없어지고 있어요.' },
    { n: 4, img: 'data:image/png;base64,', name: '많이 마른 상태', days: '기록을 5~7일 놓쳤어요',  msg: '많이 말라 힘이 없어요…' },
    { n: 5, img: 'data:image/png;base64,', name: '바싹 마른 상태', days: '기록을 7일 이상 놓쳤어요', msg: '너무 말라 버렸어요… ㅠㅠ' },
  ];

  const TIPS = [
    { when: '아침 팁', text: '샤워를 1분만 줄여도 온수 약 12L — 데우는 에너지 0.74kWh를 함께 아껴요!' },
    { when: '저녁 팁', text: '설거지통에 물을 받아서 쓰면 하루 약 60L를 절약할 수 있어요.' },
    { when: '아침 팁', text: '양치컵 하나면 한 번 양치에 약 5L를 아낄 수 있어요.' },
  ];

  // 최근 30일 이력 (어제까지, L) — 0 = 미기록
  const RAW = [612, 580, 545, 598, 634, 521, 508, 495, 560, 541,
               605, 498, 612, 577, 530, 489, 544, 0, 610, 648,
               571, 536, 502, 478, 515, 549, 591, 560, 533, 506];
  const _today = new Date();
  const HISTORY = RAW.map((L, i) => {
    const d = new Date(_today);
    d.setDate(d.getDate() - (RAW.length - i));
    return { date: d, liters: L, recorded: L > 0 };
  });

  // 어제부터 거꾸로 연속 기록일
  let STREAK = 0;
  for (let i = HISTORY.length - 1; i >= 0 && HISTORY[i].recorded; i--) STREAK++;

  const GOAL_BY_HOUSEHOLD = { '1인': 250, '2인': 380, '3인': 480, '4인 이상': 550 };

  function fmtDate(d) { return (d.getMonth() + 1) + '/' + d.getDate(); }
  function dayName(d) { return ['일', '월', '화', '수', '목', '금', '토'][d.getDay()]; }
  function fmt1(n) { return (Math.round(n * 10) / 10).toLocaleString('ko-KR', { maximumFractionDigits: 1 }); }


const BG = {
  COEF, HOT_KWH_PER_L, PER_LITER_KWH, energyOf,
  METER_YESTERDAY, SCENARIOS, STAGES, TIPS, HISTORY, STREAK,
  GOAL_BY_HOUSEHOLD, fmtDate, dayName, fmt1,
}

export default BG
